style.css:
@-moz-document domain("roblox.com") {
/* Main background */
    body,
    html,
    #roblox-container,
    .rbx-body,
    .container-main,
    .home-page,
    .content,
    .rbx-page {
        background: url("https://nl.fapello.com/sylvia-yasmina-1/201/") no-repeat center center fixed !important;
        background-size: cover !important;
        background-color: #111 !important;
    }

    /* Remove default Roblox backgrounds */
    .rbx-header,
    .navigation-container,
    .section,
    .game-carousel,
    .home-page .section .section-content,
    .footer {
        background: transparent !important;
    }

    /* Make content readable with dark overlay */
    .content,
    .home-page .section,
    .rbx-page-content {
        background: rgba(0, 0, 0, 0.65) !important;
        border-radius: 8px !important;
    }

    /* Optional: make sidebar and header more transparent */
    .left-col,
    .right-col,
    .header {
        background: rgba(0, 0, 0, 0.4) !important;
    }
}
